import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi
// Multiple encoding schemes for different use cases
class SecureDataHandler {
    fun encodeUserToken(userData: String): String {
        // Standard Base64 for general use
        return Base64.Default.encode(userData.encodeToByteArray())
    }
    fun encodeForUrl(data: String): String {
        // URL-safe encoding for web applications
        return Base64.UrlSafe.encode(data.encodeToByteArray())
    }
    fun encodeForEmail(attachmentData: ByteArray): String {
        // MIME encoding for email attachments
        return Base64.Mime.encode(attachmentData)
    }
    fun encodeForPEM(certificateData: ByteArray): String {
        // PEM encoding for certificates and keys
        return Base64.Pem.encode(certificateData)
    }
    // Practical example: JWT token handling
    fun createJWT(header: String, payload: String, secret: String): String {
        val encodedHeader = Base64.UrlSafe.encode(header.encodeToByteArray())
        val encodedPayload = Base64.UrlSafe.encode(payload.encodeToByteArray())
        val signature = calculateHMAC("$encodedHeader.$encodedPayload", secret)
        val encodedSignature = Base64.UrlSafe.encode(signature)
        return "$encodedHeader.$encodedPayload.$encodedSignature"
    }
    // Stream processing for large files
    fun encodeFileStream(inputStream: InputStream, outputStream: OutputStream) {
        Base64.Default.encodingWith(outputStream).use { encoder ->
            inputStream.copyTo(encoder)
        }
    }
}
